<div class="admin-page-actions"><div><span class="admin-kicker">Inventario</span><h2>Todos los productos</h2><p>Catálogo conectado a PostgreSQL.</p></div><a class="admin-primary-button" href="<?=e(url('admin-product-create'))?>">+ Agregar producto</a></div>
<section class="admin-panel"><div class="admin-filters"><label><span>Buscar</span><input class="form-control" type="search" placeholder="Nombre o código" data-admin-product-search></label><label><span>Categoría</span><select class="form-select" data-admin-category-filter><option value="">Todas</option><?php foreach($adminCategories as $c):?><option value="<?=e($c['nombre'])?>"><?=e($c['nombre'])?></option><?php endforeach;?></select></label></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Producto</th><th>Código</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($adminProducts as $p):?><tr data-product-row data-name="<?=e(mb_strtolower($p['nombre'].' '.($p['codigo_barra']??'')))?>" data-category="<?=e($p['categoria_nombre'])?>"><td><div class="admin-product-cell"><img src="<?=e(product_image($p['imagen']))?>" alt="" width="52" height="52"><strong><?=e($p['nombre'])?></strong></div></td><td><?=e($p['codigo_barra']??'—')?></td><td><?=e($p['categoria_nombre'])?></td><td><?=e(money($p['precio']))?></td><td><?=e($p['stock'])?></td><td><span class="admin-status"><?=in_array($p['activo'],[true,1,'t'],true)?'Activo':'Inactivo'?></span></td><td><div class="admin-row-actions"><a href="<?=e(url('admin-product-edit',['id'=>$p['id_producto']]))?>">Editar</a><form method="post" action="<?=e(url('admin-product-toggle',['id'=>$p['id_producto']]))?>"><?=csrf_input()?><button type="submit"><?=in_array($p['activo'],[true,1,'t'],true)?'Desactivar':'Activar'?></button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$adminProducts):?><p class="admin-empty">Todavía no hay productos.</p><?php endif;?></div></section>
